# -*- coding: utf-8 -*-
B=[
dict(a=1,z=4,star=3,
lit='「耶和華的話又臨到我說：你不可在這地方娶妻，生兒養女。因為耶和華論到在這地方生的兒女，和在這地國中生養他們的母親與父親，這樣說：他們要死於惡疾，沒有人為他們哀哭，也不得埋葬；他們要像地面上的糞土；他們要因刀劍和饑荒滅絕；他們的屍體要作空中飛鳥和地上走獸的食物。」',
key=[('娶','H3947','tiqakh','取、娶'),('哀哭','H5594','yissafedu','舉哀、哀悼'),('埋葬','H6912','yiqqaveru','葬埋'),('糞土','H1828','ledomen','糞、肥料'),('滅絕','H3615','yikhlu','完結、滅盡')],
gram=['**{H5594}**（safad，哀哭）：這是古代近東**正式的舉哀**，包括哭喪、捶胸、為死者哀悼。**一個社會連哀哭都沒有，是人的尊嚴被剝奪的最後一步。**','**{H3947}**（laqakh，取、娶）：「取妻」是日常婚姻語言。神**禁止**先知做**一件最正常、最被祝福的事**（創二章二十四節）。這個禁令本身就是**一篇講道**。'],
exp=['十六章一節的第一句話就很特別：神的話臨到先知，叫他不要娶妻、不要生兒養女。這在舊約是**非常罕見**的命令：婚姻與兒女，是神在創世記就賜下的祝福，現在卻成了**被禁止的事**。','原因在三、四節：在這地方生的兒女、生養他們的父母，**都要死於惡疾，沒有人哀哭，也不得葬埋**。先知的**單身**，不是他個人的缺陷，也不是神對他的懲罰，而是**一個活出來的信息**：這個地方，已經**沒有未來了**。','我們要特別溫柔地讀這一段。今天有很多單身的人、不孕的夫妻、失去孩子的父母，讀到這一節，可能會心痛。請記得：**這是神對耶利米個人在特定時刻的命令，不是對單身或不孕的人的評價。**耶利米的單身是為了傳達信息，不是因為他不配有家。']),
dict(a=5,z=7,star=3,
lit='「耶和華這樣說：你不要進入哀悼的家，不要去哀哭，也不要為他們悲傷；因為我已把我的平安、我的慈愛和憐憫，從這百姓收回了，這是耶和華說的。大的小的都要死在這地，不得埋葬，人也不為他們哀哭，不為他們劃傷自己，不為他們剃光頭髮；人不為哀悼的人擘餅，安慰他們因死人所受的痛；為喪父喪母的，也不給他們一杯安慰的酒。」',
key=[('喪家','H4798','marzeakh','哀悼的聚會、喪筵'),('悲傷','H5110','tanod','搖頭哀悼'),('平安','H7965','shalomi','我的平安'),('慈愛','H2617','hakhesed','慈愛、恆久的愛'),('憐憫','H7356','harakhamim','憐憫、慈悲'),('劃傷','H1413','yitgodad','劃破身體（哀悼的習俗）')],
gram=['**{H2617}**（khesed，慈愛）：這個字是**舊約最重要的一個字**，指神**守約的愛**。「我已把我的平安、慈愛、憐憫收回」是**整本書最重的一句話之一**：不是說神的本性改變了，而是說**在這個審判的時刻，神把它們暫時收了起來。**','**{H4798}**（marzeakh，喪筵）：這個字在阿摩司書六章七節也出現，指一種**帶有宴飲的喪禮聚會**。先知被禁止進入這種聚會。'],
exp=['五至七節把「不娶妻」的信息**推進一步**：先知不但不能有自己的家庭，也**不能進入別人的喪家**。哀悼，是人類最基本的**愛的表達**。神禁止先知去哀悼，意思是：**這一代，連為死者哭的力量，都要被收走了。**','五節有整段最沉重的一句話：我已把我的平安、慈愛、憐憫從這百姓收回了。**慈愛**（khesed）是神**守約的愛**；現在，神把它從這個世代**收回**。請小心讀：這不是說神的本性改變，而是**審判到來之時，保護被撤去**。','先知的這個行動，是**一個啞劇的講道**：他不去喪家，人們就會問：為什麼？他就可以回答。**一個人的生活，可以成為神的話。**這是耶利米的呼召的代價：**他的身體，也是信息的一部分。**']),
dict(a=8,z=9,star=2,
lit='「你不可進入宴席的家，與他們同坐吃喝。因為萬軍之耶和華、以色列的神這樣說：看哪，在你們眼前，在你們的日子裡，我要使歡喜的聲音、快樂的聲音、新郎的聲音、新婦的聲音，從這地方止息。」',
key=[('宴席','H4960','mishteh','宴席、酒席'),('止息','H7673','mashbit','使停止'),('歡喜','H8342','sason','歡喜'),('快樂','H8057','simkhah','喜樂'),('新郎','H2860','khatan','新郎'),('新婦','H3618','kallah','新娘')],
gram=['**{H8342}**（sason，歡喜）、**{H8057}**（simkhah，快樂）、**{H2860}**（khatan，新郎）、**{H3618}**（kallah，新婦）：這四個詞連用，是**耶利米書的追蹤句**，在七章三十四節、十六章九節、二十五章十節、三十三章十一節都出現。前三處是**止息**，**第四處（三十三章）是恢復**。這一句話，是整卷書的**審判與盼望的縮影**。'],
exp=['八節接著說：**也不要進入宴席的家**。哀悼的家不能去，歡笑的家也不能去。先知被放在**兩邊都不能參與**的位置：不與哭的人同哭，也不與笑的人同笑。**這是一個非常孤單的呼召。**','九節是**整章的第一個高峰**：我要使歡喜的聲音、快樂的聲音、新郎的聲音、新婦的聲音，從這地方止息。這是一個**很美的畫面**：婚禮的聲音，是人間最歡樂的聲音。神說：我要讓它停止。','請記住這句話，因為它後面還會再出現（七章三十四節、二十五章十節），最後在**三十三章十一節**，這句話**翻轉**成：「必再聽見歡喜和快樂的聲音，新郎和新婦的聲音」。**止息的聲音，將來要回來。**']),
dict(a=10,z=13,star=3,
lit='「你把這一切的話告訴這百姓，他們若對你說：耶和華為什麼說這一切大災禍要臨到我們？我們有什麼罪孽？我們向耶和華我們的神犯了什麼罪？你就對他們說：耶和華說：因為你們的列祖離棄了我，去跟從別神，事奉敬拜它們，卻離棄了我，沒有遵守我的律法；你們行惡比你們的列祖更甚，看哪，你們各人隨著自己頑梗的惡心行事，不聽從我。所以我要把你們從這地拋出去，到你們和你們列祖都不認識的地，你們在那裡要晝夜事奉別神，因為我不再施恩給你們。」',
key=[('罪孽','H5771','avoneinu','罪孽'),('頑梗','H8307','sheririt','頑固、剛硬'),('律法','H8451','torati','我的律法、訓誨'),('拋出去','H2904','vehetalti','拋擲、摔出去'),('施恩','H2594','khaninah','恩惠、恩典')],
gram=['**{H8307}**（sherirut，頑梗）：這個字是耶利米書的**追蹤字**，出現在三章十七節、七章二十四節、九章十四節、十一章八節、十三章十節、十六章十二節，是**對人心最精準的診斷**：不是無知，而是**心硬**。','**{H2904}**（tul，拋擲）：這個字用於**把東西拋出去**（撒上十八章十一節，掃羅拋槍），語氣很重。神說：**我要把你們拋出這地。**'],
exp=['十至十三節是一個**預先設計好的問答**：神預知百姓會問：為什麼？我們做了什麼？神要先知有**現成的答案**。這是很特別的一段：**神預備了先知的回答，也預備了我們的質問。**','答案有**三層**：第一，**列祖離棄神**，跟從別神；第二，**你們比列祖更惡**；第三，**你們各人隨自己頑梗的心行事，不聽從我**。這是一個**由外到內**的診斷：歷史、世代、個人。**最後的根源，是每一個人的心。**','請留意：十二節的「頑梗」（sherirut）是整卷書最精準的**人心診斷**。這不是在說百姓**愚蠢**，而是在說他們**心硬**。心硬的人，不是不知道，而是**不肯聽**。這與十三章十節呼應。']),
dict(a=14,z=15,star=3,
lit='「所以，看哪，日子將到，這是耶和華說的，人不再說：指著那領以色列人從埃及地上來的永生的耶和華起誓；卻要說：指著那領以色列人從北方之地，和從他所趕散他們的各地上來的永生的耶和華起誓；我要把他們領回他們列祖之地。」',
key=[('北方','H6828','tsafon','北方'),('趕散','H5080','hiddikhim','驅散、趕逐'),('領回','H7725','vahashivotim','使他們回來'),('地土','H127','adamatam','他們的土地')],
gram=['**{H7725}**（shuv，回轉）：「我要領他們回」是 **hifil 使役式**：神**使他們回來**。同一個字，是「你們要回轉」的字根；現在，**神自己要使他們回來**。這是整卷書**最深的轉折之一**：人不能回，神使人回。'],
exp=['十四、十五節是**突然出現的盼望**，像是黑夜中的一道光。在審判宣告的中間，神忽然說：日子將到，人不再指著**領以色列人出埃及的神**起誓，而要指著**領他們從北方回來的神**起誓。','這是一個**驚人的比較**：出埃及，是以色列人最偉大的救贖歷史，是他們信仰的核心。神說：**將來有一個救贖，會比出埃及更大。**這個應許，在二十三章七至八節又出現一次，在三十一章更展開。','請留意這一段的位置：就在**審判最重**的地方，**盼望被放進來**。這是耶利米書的寫作方式：**審判與應許，交織出現。**神不是先審判、再盼望，而是**在審判的當中，同時說出盼望**。']),
dict(a=16,z=18,star=2,
lit='「看哪，我要差遣許多漁夫，他們要打撈他們；然後我要差遣許多獵人，從各山、各岡、各石縫中獵取他們。因為我的眼目察看他們的一切行為，這些行為在我面前沒有隱藏，他們的罪孽也沒有在我眼前遮掩。我要先加倍報應他們的罪孽和罪惡，因為他們用可憎之物的屍體玷污了我的地，又用可厭之物充滿我的產業。」',
key=[('漁夫','H1771','dayyagim','打魚的人'),('獵人','H6719','tsayyadim','打獵的人'),('石縫','H5357','minqiqei','岩縫'),('加倍','H4932','mishneh','雙倍'),('可憎之物','H8251','shiqqutseihem','可憎的偶像'),('隱藏','H5641','nistaru','被隱藏')],
gram=['**{H4932}**（mishneh，雙倍）：「加倍報應」不是說神過分，而是**法律用語**（出二十二章四、七、九節）：**按律例，雙倍賠償。**這是對**偶像之罪**的嚴肅對待。','**{H8251}**（shiqquts，可憎之物）：這個字是**偶像的專稱**，在申命記裡常出現。**可憎**是神的判斷，不是人的偏見。'],
exp=['十六至十八節是**兩種捕捉者**的畫面：先有漁夫，後有獵人。漁夫用網，是**一網打盡**；獵人去山上、岡上、石縫裡找，是**一個一個搜**。意思是：**沒有人能躲過。**這是一個很嚴厲的畫面，神的審判**徹底、無處可藏**。','十七節說：我的眼目察看他們的一切行為，他們不能在我面前遮掩。這句話有**兩面**：對犯罪的人，是警告；對受苦的人，是安慰（因為神看見）。**一位全知的神，既知道我們的罪，也知道我們的苦。**','十八節說「加倍報應」：請小心讀。這是**當時的法律用語**，指按律例的雙倍賠償，是說神**嚴肅對待偶像之罪**，不是說神殘忍。偶像不是小事：**它污穢了神的地，充滿了神的產業。**']),
dict(a=19,z=21,star=3,
lit='「耶和華啊，你是我的力量，我的保障，在苦難的日子是我的避難所；列國要從地極來到你這裡，說：我們的列祖所承受的，不過是謊言，是虛空，是毫無益處的。人豈能為自己製造神呢？那些根本不是神！所以，看哪，我要使他們知道，這一次我要使他們知道我的手和我的能力；他們就要知道我的名是耶和華。」',
key=[('力量','H5797','uzzi','我的力量'),('保障','H4581','uma-uzzi','我的堡壘'),('避難所','H4498','umanusi','我的逃避之處'),('虛空','H1892','hevel','一口氣、虛空'),('能力','H1369','gevurati','我的能力'),('名','H8034','shemi','我的名')],
gram=['**{H1892}**（hevel，虛空）：這個字就是傳道書的「虛空」，本義是**一口氣、水氣**。偶像是**一口氣**：看起來有形，抓不住。','**{H8034}**（shem，名）：「他們就要知道我的名是耶和華」是**出埃及記的主題**（出六章三節）：**神的名，要被人認識。**'],
exp=['十九節是先知的**一句讚美**，出現在審判的最中間：耶和華啊，你是我的力量，我的保障，在苦難之日是我的避難所。**這是整章最溫柔的一句話。**先知被禁止娶妻、被禁止弔喪、被禁止赴宴，他一無所有，可是他說：**我有祢。**','然後先知看見一個**異象**：列國要從地極來到神這裡，說：我們列祖所承受的，不過是謊言，是虛空。這是一個**很大的盼望**：連外邦人也要回轉。這是整卷書的**宣教視野**，也預告了新約的福音要傳到地極。','二十節的問句很簡潔：**人豈能為自己製造神呢？**這是聖經對偶像最簡短的**邏輯批判**：被造的，不能製造創造者。二十一節是結論：神要使他們知道祂的手與能力，就知道祂的名是**耶和華**。**一切的審判，最終都是為了讓人認識祂。**']),
]
